export interface CanvasNode {
  id: string;
  x: number;
  y: number;
  width: number;
  height: number;
  zIndex?: number;
  locked?: boolean;
  /** Arbitrary consumer payload — the engine never inspects this. */
  data?: unknown;
}

export interface CanvasViewport {
  x: number;
  y: number;
  zoom: number;
}

export interface CanvasConfig {
  minZoom?: number; // default 0.1
  maxZoom?: number; // default 4
  /** Snap dragged node positions to this grid size (px). 0 disables snapping. */
  gridSnap?: number; // default 0
  /** Which pointer interaction pans the canvas. Default "drag" (empty-space drag). */
  panTrigger?: "drag" | "space-drag" | "middle-mouse";
}

export type CanvasDragState =
  | { type: "none" }
  | { type: "pan"; startClientX: number; startClientY: number; startViewport: CanvasViewport }
  | { type: "node-drag"; ids: string[]; startPositions: Record<string, { x: number; y: number }>; startClientX: number; startClientY: number }
  | { type: "select-box"; startX: number; startY: number; currentX: number; currentY: number };

export interface CanvasEngine {
  getViewport: () => CanvasViewport;
  getNodes: () => CanvasNode[];
  getSelection: () => Set<string>;
  getDragState: () => CanvasDragState;

  // DOM attachment — engine writes transforms directly to these for perf.
  attachViewportElement: (el: HTMLElement | null) => void;
  attachWorldElement: (el: HTMLElement | null) => void;
  registerNodeElement: (id: string, el: HTMLElement | null) => void;

  // Viewport
  panStart: (clientX: number, clientY: number) => void;
  panMove: (clientX: number, clientY: number) => void; // writes DOM directly, no re-render
  panEnd: () => void; // syncs React snapshot
  zoomTo: (zoom: number, originClient?: { x: number; y: number }) => void;
  zoomToFit: (padding?: number) => void;
  centerOn: (nodeId: string) => void;

  // Selection
  select: (ids: string[], mode?: "replace" | "add" | "toggle") => void;
  clearSelection: () => void;
  startSelectBox: (clientX: number, clientY: number) => void;
  updateSelectBox: (clientX: number, clientY: number) => void;
  endSelectBox: (mode?: "replace" | "add") => void;

  // Node drag
  startNodeDrag: (ids: string[], clientX: number, clientY: number) => void;
  updateNodeDrag: (clientX: number, clientY: number) => void; // writes DOM directly, no re-render
  endNodeDrag: () => void; // commits final positions, syncs React snapshot

  // Nodes (immutable — returns new arrays, matches Sortable/Palette convention)
  addNode: (node: CanvasNode) => void;
  removeNode: (id: string) => void;
  updateNode: (id: string, patch: Partial<Omit<CanvasNode, "id">>) => void;
  moveNodes: (ids: string[], dx: number, dy: number) => void;

  // Coordinate conversion — screen (client) px <-> canvas (world) px
  screenToCanvas: (clientX: number, clientY: number) => { x: number; y: number };
  canvasToScreen: (x: number, y: number) => { x: number; y: number };

  // Lifecycle
  subscribe: (listener: () => void) => () => void; // for React to re-render on relevant changes
  destroy: () => void;
}

export interface CanvasContextValue {
  engine: CanvasEngine;
  config: Required<CanvasConfig>;
  // React-visible snapshot — updated via engine.subscribe, NOT on every pointer-move
  nodes: CanvasNode[];
  viewport: CanvasViewport;
  selection: Set<string>;
  dragState: CanvasDragState;
}

import type {
  CanvasConfig,
  CanvasDragState,
  CanvasEngine,
  CanvasNode,
  CanvasViewport,
} from "./types";

const DEFAULT_CONFIG: Required<CanvasConfig> = {
  minZoom: 0.1,
  maxZoom: 4,
  gridSnap: 0,
  panTrigger: "drag",
};

function clamp(v: number, min: number, max: number) {
  return Math.min(max, Math.max(min, v));
}

function snap(v: number, grid: number) {
  return grid > 0 ? Math.round(v / grid) * grid : v;
}

export function createCanvasEngine(
  initialNodes: CanvasNode[],
  initialViewport: CanvasViewport,
  configInput: CanvasConfig = {},
  onChange?: (nodes: CanvasNode[]) => void,
): CanvasEngine {
  const config: Required<CanvasConfig> = { ...DEFAULT_CONFIG, ...configInput };

  let nodes = initialNodes;
  let viewport = initialViewport;
  let selection = new Set<string>();
  let dragState: CanvasDragState = { type: "none" };

  let viewportEl: HTMLElement | null = null;
  let worldEl: HTMLElement | null = null;
  const nodeElements = new Map<string, HTMLElement>();

  const listeners = new Set<() => void>();
  function notify() {
    listeners.forEach((l) => l());
  }

  function applyViewportTransform() {
    if (!worldEl) return;
    worldEl.style.transform = `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.zoom})`;
    worldEl.style.transformOrigin = "0 0";
  }

  function viewportRect() {
    return viewportEl?.getBoundingClientRect() ?? { left: 0, top: 0, width: 0, height: 0 };
  }

  function screenToCanvas(clientX: number, clientY: number) {
    const rect = viewportRect();
    const localX = clientX - rect.left;
    const localY = clientY - rect.top;
    return {
      x: (localX - viewport.x) / viewport.zoom,
      y: (localY - viewport.y) / viewport.zoom,
    };
  }

  function canvasToScreen(x: number, y: number) {
    const rect = viewportRect();
    return {
      x: rect.left + x * viewport.zoom + viewport.x,
      y: rect.top + y * viewport.zoom + viewport.y,
    };
  }

  // ─── Pan ────────────────────────────────────────────────────────────────────
  // panMove writes the transform directly and skips notify() — pan happens on
  // every pointermove, so re-rendering React for it would defeat the point.
  // panEnd() fires notify() once so anything reading viewport (zoom controls,
  // minimap, etc.) catches up to the final position.

  let panOrigin = { clientX: 0, clientY: 0, viewport: { x: 0, y: 0, zoom: 1 } };

  function panStart(clientX: number, clientY: number) {
    dragState = { type: "pan", startClientX: clientX, startClientY: clientY, startViewport: viewport };
    panOrigin = { clientX, clientY, viewport };
  }

  function panMove(clientX: number, clientY: number) {
    if (dragState.type !== "pan") return;
    const dx = clientX - panOrigin.clientX;
    const dy = clientY - panOrigin.clientY;
    viewport = { ...panOrigin.viewport, x: panOrigin.viewport.x + dx, y: panOrigin.viewport.y + dy };
    applyViewportTransform();
  }

  function panEnd() {
    dragState = { type: "none" };
    notify();
  }

  // ─── Zoom ───────────────────────────────────────────────────────────────────

  function zoomTo(zoom: number, originClient?: { x: number; y: number }) {
    const clamped = clamp(zoom, config.minZoom, config.maxZoom);

    if (originClient) {
      const before = screenToCanvas(originClient.x, originClient.y);
      const rect = viewportRect();
      const localX = originClient.x - rect.left;
      const localY = originClient.y - rect.top;
      viewport = {
        x: localX - before.x * clamped,
        y: localY - before.y * clamped,
        zoom: clamped,
      };
    } else {
      viewport = { ...viewport, zoom: clamped };
    }

    applyViewportTransform();
    notify();
  }

  function nodeBounds() {
    if (nodes.length === 0) return null;
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const n of nodes) {
      minX = Math.min(minX, n.x);
      minY = Math.min(minY, n.y);
      maxX = Math.max(maxX, n.x + n.width);
      maxY = Math.max(maxY, n.y + n.height);
    }
    return { minX, minY, maxX, maxY, width: maxX - minX, height: maxY - minY };
  }

  function zoomToFit(padding = 40) {
    const bounds = nodeBounds();
    const rect = viewportRect();
    if (!bounds || rect.width === 0 || rect.height === 0) return;

    const scaleX = (rect.width - padding * 2) / (bounds.width || 1);
    const scaleY = (rect.height - padding * 2) / (bounds.height || 1);
    const zoom = clamp(Math.min(scaleX, scaleY), config.minZoom, config.maxZoom);

    viewport = {
      x: (rect.width - bounds.width * zoom) / 2 - bounds.minX * zoom,
      y: (rect.height - bounds.height * zoom) / 2 - bounds.minY * zoom,
      zoom,
    };

    applyViewportTransform();
    notify();
  }

  function centerOn(nodeId: string) {
    const node = nodes.find((n) => n.id === nodeId);
    const rect = viewportRect();
    if (!node || rect.width === 0) return;

    const cx = node.x + node.width / 2;
    const cy = node.y + node.height / 2;

    viewport = {
      ...viewport,
      x: rect.width / 2 - cx * viewport.zoom,
      y: rect.height / 2 - cy * viewport.zoom,
    };

    applyViewportTransform();
    notify();
  }

  // ─── Selection ──────────────────────────────────────────────────────────────

  function select(ids: string[], mode: "replace" | "add" | "toggle" = "replace") {
    if (mode === "replace") {
      selection = new Set(ids);
    } else if (mode === "add") {
      selection = new Set(selection);
      ids.forEach((id) => selection.add(id));
    } else {
      selection = new Set(selection);
      ids.forEach((id) => (selection.has(id) ? selection.delete(id) : selection.add(id)));
    }
    notify();
  }

  function clearSelection() {
    selection = new Set();
    notify();
  }

  // Selection box is rendered by React (it's a thin overlay div, not a perf-critical
  // surface like node/pan dragging), so unlike pan/node-drag this DOES notify on every
  // move — the tradeoff is acceptable since it's a short-lived, low-frequency-enough gesture.
  function startSelectBox(clientX: number, clientY: number) {
    const p = screenToCanvas(clientX, clientY);
    dragState = { type: "select-box", startX: p.x, startY: p.y, currentX: p.x, currentY: p.y };
    notify();
  }

  function updateSelectBox(clientX: number, clientY: number) {
    if (dragState.type !== "select-box") return;
    const p = screenToCanvas(clientX, clientY);
    dragState = { ...dragState, currentX: p.x, currentY: p.y };
    notify();
  }

  function endSelectBox(mode: "replace" | "add" = "replace") {
    if (dragState.type !== "select-box") return;
    const { startX, startY, currentX, currentY } = dragState;
    const minX = Math.min(startX, currentX);
    const maxX = Math.max(startX, currentX);
    const minY = Math.min(startY, currentY);
    const maxY = Math.max(startY, currentY);

    const hitIds = nodes
      .filter((n) => n.x < maxX && n.x + n.width > minX && n.y < maxY && n.y + n.height > minY)
      .map((n) => n.id);

    dragState = { type: "none" };
    select(hitIds, mode);
  }

  // ─── Node drag ──────────────────────────────────────────────────────────────
  // updateNodeDrag writes a translate() directly to each dragged node's element
  // and skips notify() — same rationale as pan. endNodeDrag commits the final
  // delta into node state (immutably) in one shot and clears the inline transform.

  function startNodeDrag(ids: string[], clientX: number, clientY: number) {
    const startPositions: Record<string, { x: number; y: number }> = {};
    ids.forEach((id) => {
      const n = nodes.find((node) => node.id === id);
      if (n) startPositions[id] = { x: n.x, y: n.y };
    });
    dragState = { type: "node-drag", ids, startPositions, startClientX: clientX, startClientY: clientY };
  }

  function updateNodeDrag(clientX: number, clientY: number) {
    if (dragState.type !== "node-drag") return;
    const rawDx = (clientX - dragState.startClientX) / viewport.zoom;
    const rawDy = (clientY - dragState.startClientY) / viewport.zoom;

    dragState.ids.forEach((id) => {
      const el = nodeElements.get(id);
      if (el) el.style.transform = `translate(${rawDx}px, ${rawDy}px)`;
    });
  }

  function endNodeDrag() {
    if (dragState.type !== "node-drag") return;
    const { ids } = dragState;

    // Read the last-applied transform off the first dragged element to get the final delta.
    const sampleId = ids[0];
    const el = sampleId ? nodeElements.get(sampleId) : null;
    let dx = 0;
    let dy = 0;
    if (el) {
      const match = /translate\(([-\d.]+)px,\s*([-\d.]+)px\)/.exec(el.style.transform);
      if (match) {
        dx = snap(parseFloat(match[1]), config.gridSnap);
        dy = snap(parseFloat(match[2]), config.gridSnap);
      }
    }

    ids.forEach((id) => {
      const elm = nodeElements.get(id);
      if (elm) elm.style.transform = "";
    });

    dragState = { type: "none" };
    if (dx !== 0 || dy !== 0) {
      moveNodes(ids, dx, dy);
    } else {
      notify();
    }
  }

  // ─── Nodes ──────────────────────────────────────────────────────────────────

  function addNode(node: CanvasNode) {
    nodes = [...nodes, node];
    onChange?.(nodes);
    notify();
  }

  function removeNode(id: string) {
    nodes = nodes.filter((n) => n.id !== id);
    if (selection.has(id)) {
      selection = new Set(selection);
      selection.delete(id);
    }
    onChange?.(nodes);
    notify();
  }

  function updateNode(id: string, patch: Partial<Omit<CanvasNode, "id">>) {
    nodes = nodes.map((n) => (n.id === id ? { ...n, ...patch } : n));
    onChange?.(nodes);
    notify();
  }

  function moveNodes(ids: string[], dx: number, dy: number) {
    const idSet = new Set(ids);
    nodes = nodes.map((n) => (idSet.has(n.id) ? { ...n, x: n.x + dx, y: n.y + dy } : n));
    onChange?.(nodes);
    notify();
  }

  return {
    getViewport: () => viewport,
    getNodes: () => nodes,
    getSelection: () => selection,
    getDragState: () => dragState,

    attachViewportElement: (el) => {
      viewportEl = el;
    },
    attachWorldElement: (el) => {
      worldEl = el;
      applyViewportTransform();
    },
    registerNodeElement: (id, el) => {
      if (el) nodeElements.set(id, el);
      else nodeElements.delete(id);
    },

    panStart,
    panMove,
    panEnd,
    zoomTo,
    zoomToFit,
    centerOn,

    select,
    clearSelection,
    startSelectBox,
    updateSelectBox,
    endSelectBox,

    startNodeDrag,
    updateNodeDrag,
    endNodeDrag,

    addNode,
    removeNode,
    updateNode,
    moveNodes,

    screenToCanvas,
    canvasToScreen,

    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
    destroy: () => {
      listeners.clear();
      nodeElements.clear();
    },
  };
}

"use client";

import * as React from "react";
import type { CanvasContextValue } from "./types";

export const CanvasCtx = React.createContext<CanvasContextValue | null>(null);

export function useCanvasCtx(): CanvasContextValue {
  const ctx = React.useContext(CanvasCtx);
  if (!ctx) throw new Error("useCanvasCtx must be used inside CanvasRoot");
  return ctx;
}

"use client";

import * as React from "react";
import { CanvasCtx } from "./canvas-context";
import { createCanvasEngine } from "./canvas-engine";
import { CanvasViewport } from "./canvas-viewport";
import type { CanvasConfig, CanvasNode } from "./types";

export interface CanvasRootProps {
  defaultNodes?: CanvasNode[];
  onChange?: (nodes: CanvasNode[]) => void;
  config?: CanvasConfig;
  /** Renders a single node's content. The engine handles position/selection/drag — you only render what's inside. */
  renderNode?: (node: CanvasNode, isSelected: boolean) => React.ReactNode;
  className?: string;
  /** Replace the default viewport layout entirely. */
  children?: React.ReactNode;
}

export function CanvasRoot({
  defaultNodes = [],
  onChange,
  config = {},
  renderNode,
  className,
  children,
}: CanvasRootProps) {
  const [engine] = React.useState(() =>
    createCanvasEngine(defaultNodes, { x: 0, y: 0, zoom: 1 }, config, onChange),
  );

  // Forces a re-render whenever the engine calls notify() — pan/node-drag skip this
  // on every pointermove by design (see canvas-engine.ts), so this fires far less
  // often than the underlying pointer events.
  const [, forceUpdate] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => engine.subscribe(forceUpdate), [engine]);
  React.useEffect(() => () => engine.destroy(), [engine]);

  const resolvedConfig: Required<CanvasConfig> = {
    minZoom: config.minZoom ?? 0.1,
    maxZoom: config.maxZoom ?? 4,
    gridSnap: config.gridSnap ?? 0,
    panTrigger: config.panTrigger ?? "drag",
  };

  const ctx = {
    engine,
    config: resolvedConfig,
    nodes: engine.getNodes(),
    viewport: engine.getViewport(),
    selection: engine.getSelection(),
    dragState: engine.getDragState(),
  };

  return (
    <CanvasCtx.Provider value={ctx}>
      {children ?? <CanvasViewport className={className} renderNode={renderNode} />}
    </CanvasCtx.Provider>
  );
}

CanvasRoot.displayName = "CanvasRoot";

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useCanvasCtx } from "./canvas-context";
import { CanvasNodeView } from "./canvas-node-view";
import { CanvasSelectionBox } from "./canvas-selection-box";
import type { CanvasNode } from "./types";

export interface CanvasViewportProps {
  className?: string;
  renderNode?: (node: CanvasNode, isSelected: boolean) => React.ReactNode;
}

export function CanvasViewport({ className, renderNode }: CanvasViewportProps) {
  const { engine, config, nodes, selection } = useCanvasCtx();

  const viewportRef = React.useRef<HTMLDivElement>(null);
  const worldRef = React.useRef<HTMLDivElement>(null);
  const spacePressed = React.useRef(false);

  React.useEffect(() => {
    engine.attachViewportElement(viewportRef.current);
    engine.attachWorldElement(worldRef.current);
    return () => {
      engine.attachViewportElement(null);
      engine.attachWorldElement(null);
    };
  }, [engine]);

  React.useEffect(() => {
    if (config.panTrigger !== "space-drag") return;
    function onKeyDown(e: KeyboardEvent) {
      if (e.code === "Space") spacePressed.current = true;
    }
    function onKeyUp(e: KeyboardEvent) {
      if (e.code === "Space") spacePressed.current = false;
    }
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);
    return () => {
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keyup", onKeyUp);
    };
  }, [config.panTrigger]);

  function intentFor(e: React.PointerEvent): "pan" | "select-box" {
    if (config.panTrigger === "middle-mouse") return e.button === 1 ? "pan" : "select-box";
    if (config.panTrigger === "space-drag") return spacePressed.current ? "pan" : "select-box";
    // default "drag": plain drag pans, shift+drag rubber-bands
    return e.shiftKey ? "select-box" : "pan";
  }

  function onPointerDown(e: React.PointerEvent) {
    if (e.target !== viewportRef.current && e.target !== worldRef.current) return; // hit a node, ignore

    const intent = intentFor(e);
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);

    if (intent === "pan") {
      engine.panStart(e.clientX, e.clientY);
      function onMove(ev: PointerEvent) {
        engine.panMove(ev.clientX, ev.clientY);
      }
      function onUp() {
        engine.panEnd();
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", onUp);
      }
      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
    } else {
      engine.clearSelection();
      engine.startSelectBox(e.clientX, e.clientY);
      function onMove(ev: PointerEvent) {
        engine.updateSelectBox(ev.clientX, ev.clientY);
      }
      function onUp() {
        engine.endSelectBox("replace");
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", onUp);
      }
      window.addEventListener("pointermove", onMove);
      window.addEventListener("pointerup", onUp);
    }
  }

  function onWheel(e: React.WheelEvent) {
    e.preventDefault();
    const factor = Math.exp(-e.deltaY * 0.001);
    const current = engine.getViewport().zoom;
    engine.zoomTo(current * factor, { x: e.clientX, y: e.clientY });
  }

  return (
    <div
      ref={viewportRef}
      onPointerDown={onPointerDown}
      onWheel={onWheel}
      className={cn(
        "relative h-full w-full overflow-hidden rounded-xl border border-border",
        "touch-none select-none cursor-default bg-background",
        className,
      )}
    >
      <div ref={worldRef} className="absolute left-0 top-0 h-0 w-0">
        {nodes.map((node) => (
          <CanvasNodeView key={node.id} node={node}>
            {renderNode ? renderNode(node, selection.has(node.id)) : null}
          </CanvasNodeView>
        ))}
      </div>

      <CanvasSelectionBox />
    </div>
  );
}

CanvasViewport.displayName = "CanvasViewport";

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useCanvasCtx } from "./canvas-context";
import type { CanvasNode } from "./types";

export interface CanvasNodeViewProps {
  node: CanvasNode;
  children: React.ReactNode;
  className?: string;
}

export function CanvasNodeView({ node, children, className }: CanvasNodeViewProps) {
  const { engine, selection } = useCanvasCtx();
  const isSelected = selection.has(node.id);

  const setRef = React.useCallback(
    (el: HTMLDivElement | null) => engine.registerNodeElement(node.id, el),
    [engine, node.id],
  );

  function onPointerDown(e: React.PointerEvent) {
    if (node.locked) return;
    e.stopPropagation(); // don't let CanvasViewport treat this as a pan/select-box start

    const ids = selection.has(node.id) ? Array.from(selection) : [node.id];
    if (!selection.has(node.id)) {
      engine.select([node.id], e.shiftKey ? "add" : "replace");
    }

    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    engine.startNodeDrag(ids, e.clientX, e.clientY);

    function onMove(ev: PointerEvent) {
      engine.updateNodeDrag(ev.clientX, ev.clientY);
    }
    function onUp() {
      engine.endNodeDrag();
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    }
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
  }

  return (
    <div
      ref={setRef}
      onPointerDown={onPointerDown}
      data-selected={isSelected || undefined}
      data-locked={node.locked || undefined}
      className={cn(
        "absolute select-none",
        node.locked ? "cursor-default" : "cursor-grab active:cursor-grabbing",
        isSelected && "ring-2 ring-primary ring-offset-1 ring-offset-background rounded-md",
        className,
      )}
      style={{
        left: node.x,
        top: node.y,
        width: node.width,
        height: node.height,
        zIndex: node.zIndex ?? 0,
      }}
    >
      {children}
    </div>
  );
}

CanvasNodeView.displayName = "CanvasNodeView";

"use client";

import * as React from "react";
import { useCanvasCtx } from "./canvas-context";

export function CanvasSelectionBox() {
  const { dragState, viewport } = useCanvasCtx();

  if (dragState.type !== "select-box") return null;

  const { startX, startY, currentX, currentY } = dragState;
  const minX = Math.min(startX, currentX);
  const minY = Math.min(startY, currentY);
  const width = Math.abs(currentX - startX);
  const height = Math.abs(currentY - startY);

  // Selection box lives in viewport-local pixel space — same transform math as the
  // world layer (canvas coords * zoom + pan offset) — but the box element itself is
  // NOT inside the transformed world div, so it stays crisp at 1px regardless of zoom.
  return (
    <div
      className="pointer-events-none absolute rounded-sm border border-primary bg-primary/10"
      style={{
        left: minX * viewport.zoom + viewport.x,
        top: minY * viewport.zoom + viewport.y,
        width: width * viewport.zoom,
        height: height * viewport.zoom,
      }}
    />
  );
}

CanvasSelectionBox.displayName = "CanvasSelectionBox";

import { useCanvasCtx } from "./canvas-context";

/**
 * Call from anywhere under <CanvasRoot> for programmatic control — zoomToFit,
 * centerOn, addNode, etc. — plus read access to nodes/viewport/selection.
 */
export function useCanvas() {
  const ctx = useCanvasCtx();
  return {
    nodes: ctx.nodes,
    viewport: ctx.viewport,
    selection: ctx.selection,
    dragState: ctx.dragState,
    zoomTo: ctx.engine.zoomTo,
    zoomToFit: ctx.engine.zoomToFit,
    centerOn: ctx.engine.centerOn,
    select: ctx.engine.select,
    clearSelection: ctx.engine.clearSelection,
    addNode: ctx.engine.addNode,
    removeNode: ctx.engine.removeNode,
    updateNode: ctx.engine.updateNode,
    moveNodes: ctx.engine.moveNodes,
    screenToCanvas: ctx.engine.screenToCanvas,
    canvasToScreen: ctx.engine.canvasToScreen,
  };
}

